import 'package:flutter/material.dart';

/// Represents a distinct widget variation generated by the Criador de Widgets com IA.
class WidgetVariation {
  final String id;
  final String title;
  final String styleTag; // e.g. "Glassmorphism Oval", "Bento Grid Profile", "Hero Banner"
  final String description;
  final String dartCode;
  final IconData? icon;
  final String techApproach; // e.g. "CircleAvatar + Glow + Row", "ClipRRect + Bento Grid", "Gradient Container + Action Button"

  const WidgetVariation({
    required this.id,
    required this.title,
    required this.styleTag,
    required this.description,
    required this.dartCode,
    this.icon,
    required this.techApproach,
  });

  WidgetVariation copyWith({
    String? id,
    String? title,
    String? styleTag,
    String? description,
    String? dartCode,
    IconData? icon,
    String? techApproach,
  }) {
    return WidgetVariation(
      id: id ?? this.id,
      title: title ?? this.title,
      styleTag: styleTag ?? this.styleTag,
      description: description ?? this.description,
      dartCode: dartCode ?? this.dartCode,
      icon: icon ?? this.icon,
      techApproach: techApproach ?? this.techApproach,
    );
  }

  Map<String, dynamic> toJson() {
    return {
      'id': id,
      'title': title,
      'styleTag': styleTag,
      'description': description,
      'dartCode': dartCode,
      'techApproach': techApproach,
    };
  }

  factory WidgetVariation.fromJson(Map<String, dynamic> json, {IconData? icon}) {
    return WidgetVariation(
      id: json['id'] as String? ?? '',
      title: json['title'] as String? ?? '',
      styleTag: json['styleTag'] as String? ?? '',
      description: json['description'] as String? ?? '',
      dartCode: json['dartCode'] as String? ?? '',
      icon: icon,
      techApproach: json['techApproach'] as String? ?? '',
    );
  }

  @override
  bool operator ==(Object other) {
    if (identical(this, other)) return true;
    return other is WidgetVariation &&
        other.id == id &&
        other.title == title &&
        other.styleTag == styleTag &&
        other.description == description &&
        other.dartCode == dartCode &&
        other.icon == icon &&
        other.techApproach == techApproach;
  }

  @override
  int get hashCode =>
      Object.hash(id, title, styleTag, description, dartCode, icon, techApproach);

  @override
  String toString() =>
      'WidgetVariation(id: $id, title: "$title", styleTag: "$styleTag", techApproach: "$techApproach")';
}
